//! Actions-only original physical writer user mark-read cancellation/Join.
//! Low-level IO only; it never grants Hosted/device/SDK readiness from a test.
use super::*;
use n::{account_test_support::TempDatabase,im_inbox::{ImInboxScope,UserReadAction,BoundUserRead}};
fn original(temp:&TempDatabase,root:&str)->(AttemptOwner,Arc<n::account_runs::RunToken>){let line="app-account-0123456789abcdef0123456789abcdef";let mut c=n::account_config::tests::native_fixture(root,"127.0.0.1",1);c.credentials.sdk.expires_at_unix_seconds=None;c.profile.incoming=None;c.profile.client_ex=true;c.profile.native_receivers=Some(super::config(true));temp.database.with_conn(|conn|n::account_store::create(conn,line,&c,100)).unwrap();let run=Arc::new(temp.database.with_conn(|c|n::account_runs::register_runtime(c,line,1,&n::account_runtime::local_nonce().unwrap())).unwrap());let mut s=n::session::HostingSession::new(line.into());s.import(n::tests::imported(),100).unwrap();(s.begin_login(100).unwrap(),run)}
fn message()->Vec<u8>{let mut b=Writer::new();b.i64(7).unwrap();b.i64(1).unwrap();b.bytes(b"fixture-sender").unwrap();b.bytes(b"Text").unwrap();b.bytes(br#"{"text":"read body"}"#).unwrap();b.properties(&[]).unwrap();b.properties(&[]).unwrap();let mut a=Writer::versioned().unwrap();a.bytes(n::im_data::MORE_MESSAGE_KIND).unwrap();a.properties(&[RpcProperty{key:b"Box",value:b"P2P/1_2"}]).unwrap();a.bytes(b.finish().expose_to_transport()).unwrap();let r=encode_request(91,&[RpcProperty{key:b"id",value:b"MessageReceiver"},RpcProperty{key:b"__magic",value:&[9,1]}],n::rpc_incoming::ONLINE_MESSAGE_METHOD.as_bytes(),a.finish().expose_to_transport()).unwrap();let mut p=vec![0];p.extend_from_slice(r.expose_to_transport());p}
fn target()->Vec<u8>{let mut w=Writer::new();w.boolean(true).unwrap();w.u32(1).unwrap();w.bytes(b"1_2").unwrap();w.properties(&[RpcProperty{key:n::im_status::LATEST,value:b"9"}]).unwrap();w.i64(1).unwrap();w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
async fn peer_ready(peer:&mut CommonPeer,go:oneshot::Receiver<()>){peer_login(peer).await;go.await.unwrap();peer.send(&[message()]).await;let p=peer.next().await.unwrap();assert_eq!(p[0],1);let r=decode_reply(&p[1..]).unwrap();assert_eq!(r.call_id,91);assert_eq!(r.result_stream,[0,1,0,0,0,0]);let p=peer.next().await.unwrap();let id=query(&p,n::im_status::REFRESH_METHOD);peer.send(&[reply(id,&target())]).await;}
async fn setup(handle:&RuntimeHandle,events:&mut mpsc::Receiver<RuntimeEvent>,who:&AttemptOwner,scope:&RpcConnectionScope,temp:&TempDatabase,run:Arc<n::account_runs::RunToken>,gate:Arc<ImReceiptGate>)->(Arc<UserReadAction>,Arc<n::im_inbox::UserReadPermit>){
    let e=bounded(events.recv()).await.unwrap();let delivery=e.into_events(who,scope).unwrap().into_iter().find_map(|e|if let OfflineEvent::Im(d)=e{Some(d)}else{None}).unwrap();let c=ImInboxScope::original(run.clone(),delivery.notice().binding().clone(),gate.clone()).unwrap();let proof=c.commit(&temp.database,&delivery).unwrap().unwrap();handle.command_handle().complete_im(who,scope,delivery.ticket(),Some(&proof)).await.unwrap();let id=temp.database.with_conn(|c|n::im_inbox::list(c,run.line_id(),16)).unwrap()[0].id;let a=UserReadAction::original(temp.database.clone(),run,gate,who.clone(),scope.clone(),id,&"a".repeat(32),Instant::now()+Duration::from_secs(3)).unwrap();let commands=handle.command_handle();let binding=commands.original_im_binding(who,scope).await.unwrap();let BoundUserRead::Context(c)=a.bind_current(binding).unwrap()else{panic!()};let r=commands.read_user_target(&a,c.query()).await.unwrap();let p=c.admit(&r).unwrap();(a,p)
}
async fn blocked(parent:bool){
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let policy=router_policy(&cert.root,listener.local_addr().unwrap().port());let server=cert.server_config(&TLS13);let(go,wait)=oneshot::channel();let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;peer_ready(&mut peer,wait).await;assert!(peer.next().await.is_none(),"blocked user write is never sent/replayed");}).await});
    let temp=TempDatabase::new();let(who,run)=original(&temp,&cert.root);let mut conn=connected(&policy,who.clone(),Instant::now()+Duration::from_secs(6)).await;let flag=Arc::new(AtomicBool::new(false));let pauses=n::common_runtime::tests::gate_im_read_write(conn.common.as_mut().unwrap(),flag.clone());let scope=conn.connection_scope();let(mut handle,mut events)=conn.attach().unwrap();auth(&handle,&mut events,&who,&scope,true).await;go.send(()).unwrap();let parent_gate=ImReceiptGate::fresh();let(action,permit)=setup(&handle,&mut events,&who,&scope,&temp,run,parent_gate.clone()).await;flag.store(true,Ordering::SeqCst);let commands=handle.command_handle();let mut f=Box::pin(commands.user_read_write(&who,&scope,permit));assert!(tokio::time::timeout(Duration::from_millis(35),&mut f).await.is_err());assert!(pauses.load(Ordering::SeqCst)>0);if parent{parent_gate.retire();assert_eq!(bounded(f).await.err(),Some(RuntimeError::Cancelled));}else{drop(f);action.cancel();}bounded(scope.closed()).await;let r=bounded(handle.close()).await;assert!(r.io_released());assert_eq!(r.reason,RuntimeError::Cancelled);let state:i64=temp.database.with_conn(|c|c.query_row("SELECT state FROM app_voice_im_user_reads",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(state,0);bounded(serving).await.unwrap();
}
#[tokio::test]async fn user_read_io_possible_partial_wait_cancel_keeps_unknown_and_closes_same_physical_owner(){Box::pin(blocked(false)).await;}
#[tokio::test]async fn user_read_io_parent_retirement_during_write_keeps_unknown_and_all_original_joins(){Box::pin(blocked(true)).await;}
